import sys

def solve():
    T = int(sys.stdin.readline())
    for _ in range(T):
        P = sys.stdin.readline().strip()
        max_jump = 1
        days = 0
        i = 1
        n = len(P)
        while i < n:
            if P[i] == '.':
                start = i
                while i < n and P[i] == '.':
                    i += 1
                gap_length = i - start
                if gap_length > max_jump:
                    max_jump = gap_length
                    days += 1
            else:
                i += 1
        print(days)

solve()
